use super::*;
fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){crate::test_allocation::observe_backing(operation)}
fn receipt(owner:&mut RetainedHistoryOpDecode,grant:RetainedCloneGrant,born:usize,released:usize)->usize{let(received,progress)=owner.take_receipt().unwrap();assert_eq!(received,grant);assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));progress.copied_bytes}
fn close_payload(mut payload:OpPayload,grant:RetainedCloneGrant)->usize{let mut releases=0;if payload.text.is_some(){let(result,born,released)=observe(||RetainedWireFieldDecode::admit_received_text(&mut payload.text,grant).unwrap());assert_eq!((born,released),(0,0));let mut owner=result.unwrap();assert_eq!(owner.take_receipt().unwrap().1.copied_bytes,0);let(_,born,released)=observe(||owner.close_step(grant).unwrap());let(received,progress)=owner.take_receipt().unwrap();assert_eq!(received,grant);assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));releases+=released;assert!(owner.terminal_is_empty());}if payload.binary.is_some(){let(result,born,released)=observe(||RetainedWireFieldDecode::admit_received(&mut payload.binary,grant).unwrap());assert_eq!((born,released),(0,0));let mut owner=result.unwrap();assert_eq!(owner.take_receipt().unwrap().1.copied_bytes,0);let(_,born,released)=observe(||owner.close_step(grant).unwrap());let(received,progress)=owner.take_receipt().unwrap();assert_eq!(received,grant);assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));releases+=released;assert!(owner.terminal_is_empty());}releases}
fn close_partial(owner:&mut RetainedHistoryOpDecode,source:&[u8],grant:RetainedCloneGrant)->usize{owner.cancel();let mut release=0;for _ in 0..64{if owner.terminal_is_empty(){return release}let mut recipient=None;let(_,born,released)=if owner.partial_is_receivable(){observe(||owner.take_partial_into(&mut recipient,grant).unwrap())}else{let demand=owner.demands(source,grant.maximum_copy_bytes).unwrap();for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:demand.depth-1,..grant}]{let(step,born,released)=observe(||owner.close_step(source,denied).unwrap());assert_eq!(step,RetainedHistoryOpDecodeStep::Blocked);assert_eq!((born,released),(0,0));}observe(||owner.close_step(source,grant).unwrap())};release+=released;assert_eq!(receipt(owner,grant,born,released),0);if let Some(payload)=recipient{release+=close_payload(payload,grant)}}panic!("original operation close did not terminate")}
#[test]
fn original_history_operation_native_fields_preserve_paid_partial_and_ready_receiving(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["grant"];let n=|key:&str|p[key].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};
 for value in law["payloads"].as_array().unwrap(){let source:Vec<u8>=value["wireHex"].as_str().unwrap().as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect();for cancellation in[0,1,3,7,64]{for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,born,released)=observe(||RetainedHistoryOpDecode::admit(&source,(0,source.len()),denied).unwrap());assert!(result.is_none());assert_eq!((born,released),(0,0));}let(result,born,released)=observe(||RetainedHistoryOpDecode::admit(&source,(0,source.len()),grant).unwrap());assert_eq!((born,released),(0,0));let mut owner=result.unwrap();assert_eq!(receipt(&mut owner,grant,born,released),0);let changed=source.clone();assert!(owner.demands(&changed,grant.maximum_copy_bytes).is_err());let(mut birth,mut release,mut copied)=(0,0,0);
  for _ in 0..cancellation{if owner.is_ready(){break}let demand=owner.demands(&source,grant.maximum_copy_bytes).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:demand.depth-1,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant}].into_iter().enumerate(){if(axis==2&&demand.capacity_bytes==0)||(axis==3&&demand.copy_bytes==0){continue}let(step,born,released)=observe(||owner.step(&source,denied).unwrap());assert_eq!(step,RetainedHistoryOpDecodeStep::Blocked);assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none());}let(_,born,released)=observe(||owner.step(&source,grant).unwrap());birth+=born;release+=released;let(step,blocked_birth,blocked_release)=observe(||owner.step(&source,grant).unwrap());assert_eq!(step,RetainedHistoryOpDecodeStep::Blocked);assert_eq!((blocked_birth,blocked_release),(0,0));copied+=receipt(&mut owner,grant,born,released);}
  if cancellation==64{assert!(owner.is_ready());let mut recipient=None;let(_,born,released)=observe(||owner.take_ready_into(&mut recipient,grant).unwrap());assert_eq!((born,released),(0,0));assert_eq!(receipt(&mut owner,grant,born,released),0);let payload=recipient.unwrap();assert_eq!(payload.text.as_deref(),value["text"].as_str());let binary_hex=payload.binary.as_ref().map(|bytes|bytes.iter().map(|byte|format!("{byte:02x}")).collect::<String>());assert_eq!(binary_hex.as_deref(),value["binaryHex"].as_str());assert_eq!(copied,payload.text.as_ref().map_or(0,String::len)+payload.binary.as_ref().map_or(0,Vec::len));release+=close_payload(payload,grant);}else{release+=close_partial(&mut owner,&source,grant)}assert!(owner.terminal_is_empty());assert_eq!(birth,release);let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));
 }}
 for source in[&[0][..],&[1,2,0xff,0xff][..],&[2,1,0,1][..]]{let mut owner=RetainedHistoryOpDecode::admit(source,(0,source.len()),grant).unwrap().unwrap();owner.take_receipt().unwrap();let mut fault=false;for _ in 0..32{match owner.step(source,grant){Ok(_)=>{owner.take_receipt();if owner.is_ready(){break}},Err(_)=>{owner.take_receipt();fault=true;break}}}assert!(fault);close_partial(&mut owner,source,grant);assert!(owner.terminal_is_empty());}
 eprintln!("[DEBUG] original History operation fields preserve exact native text/binary backing through independently funded nested original grants, paid typed ready/partial receivers and actual physical release receipts; metadata copy0 and terminalDrop0");
}
